n=0
for tk,(th,vd,vc,al) in U.items():
    esc=lambda s: s.replace('\\','\\\\').replace("'","\\'")
    rep=("    thesis:'"+esc(th)+"', verdict:'"+esc(vd)+"', verdictCls:'"+vc+"',\n    alert:'"+esc(al)+"',\n")
    pat=(r"(\n  "+tk+r": \{.*?)"
         r"\n    thesis:'(?:[^'\\]|\\.)*', verdict:'(?:[^'\\]|\\.)*', verdictCls:'[^']*',"
         r"\n    alert:'(?:[^'\\]|\\.)*',\n")
    src,k=re.subn(pat, lambda m:m.group(1)+"\n"+rep, src, flags=re.DOTALL)
    if k!=1: print(f'ERROR {tk}: {k}'); sys.exit(1)
    n+=1
open(FILE,'w').write(src); print(f'OK - {n} monitor entries refreshed'); os.remove(FILE+'.bak')
